			setStage(2);
		} else if (climate.getCurrentSeason() == Season.SUMMER && getStage() > 3) {
			setStage(3);
		} else if (climate.getCurrentSeason() == Season.AUTUMN && getStage() > 2) {
			setStage(2);
		} else if (climate.getCurrentSeason() == Season.WINTER && getStage() > 1) {
			setStage(1);
		}
	}


