		switch (climate.getCurrentSeason()) {
			case SPRING:
				if (getStage() == 2) {
					return new Color(34, 140, 61);
				} else if (getStage() == 1) {
					return new Color(68, 201, 104);
				} else {
					return new Color(131, 101, 57);
				}
			case SUMMER:
				if (getStage() == 3) {
					return new Color(11, 102, 35);
				} else if (getStage() == 2) {
					return new Color(34, 140, 61);
				} else if (getStage() == 1) {
					return new Color(68, 201, 104);
